func (s *testDB) PrevCmd(upto int, prefix string) (store.Cmd, error) {
	if s.oneOffError != nil {
		return store.Cmd{}, s.error()
	}
	if upto < 0 || upto > len(s.cmds) {
		upto = len(s.cmds)
